{
  "plan": "이 함수는 두 가지 주요 조건을 처리합니다: 일반 취소 마감 조건과 정정 기간 조건. 일반 취소 마감 조건은 이용 시작 24시간 전(86400초)까지이며, 이용 시작 시점 이후에는 거부합니다. 정정 기간 조건은 예약 생성 후 10분(600초)까지이며, 이 기간 내에 있으면 일반 취소 마감이 지난 예약도 정정할 수 있습니다. 정정 기간이 끝나는 순간도 포함합니다. 일반 취소 마감 조건은 정정 기간 조건보다 우선합니다. 아무 조건에도 해당하지 않을 때는 미정으로 처리하며, 담당자 판단이 필요할 경우 예외를 발생시킵니다.",
  "questions": [],
  "rows": [
    {
      "when": [
        {"input": "age_seconds", "op": "<", "seconds": 600},
        {"input": "until_start_seconds", "op": ">=", "seconds": 0}
      ],
      "action": "허용",
      "references": [4, 5, 6]
    },
    {
      "when": [
        {"input": "age_seconds", "op": "==", "seconds": 600},
        {"input": "until_start_seconds", "op": ">=", "seconds": 0}
      ],
      "action": "허용",
      "references": [5]
    },
    {
      "when": [
        {"input": "until_start_seconds", "op": "==", "seconds": 86400},
        {"input": "until_start_seconds", "op": "<", "seconds": 0}
      ],
      "action": "허용",
      "references": [1, 3]
    },
    {
      "when": [
        {"input": "until_start_seconds", "op": "==", "seconds": 0},
        {"input": "age_seconds", "op": "<", "seconds": 600}
      ],
      "action": "거부",
      "references": [7]
    },
    {
      "when": [
        {"input": "until_start_seconds", "op": "<", "seconds": 0},
        {"input": "age_seconds", "op": "<", "seconds": 600}
      ],
      "action": "거부",
      "references": [8]
    },
    {
      "when": [
        {"input": "age_seconds", "op": ">=", "seconds": 600}
      ],
      "action": "미정",
      "references": [9]
    }
  ],
  "fallback": {
    "action": "미정",
    "references": [9]
  },
  "complete": true
}
